  const raw = json(await ownedBytes(path, 1024 * 1024, true));
  exact(raw, ['schema', 'workspaces'], ['schema', 'workspaces']);
  if (raw.schema !== ODATA_WORKSPACE_CONNECTION_SCHEMA || !plain(raw.workspaces) ||
